        fun addVERIFIEDCHUNKS(builder: FlatBufferBuilder, verifiedChunks: Int) = builder.addOffset(31, verifiedChunks, 0)
        fun createVerifiedChunksVector(builder: FlatBufferBuilder, data: IntArray) : Int {
            builder.startVector(4, data.size, 4)
            for (i in data.size - 1 downTo 0) {
                builder.addOffset(data[i])
            }
            return builder.endVector()
        }
        fun startVerifiedChunksVector(builder: FlatBufferBuilder, numElems: Int) = builder.startVector(4, numElems, 4)
